const startProbe = trigger({
  type: 'n8n-nodes-base.manualTrigger',
  version: 1,
  config: { name: 'Start Runtime Probe', parameters: {}, position: [240, 300] },
  output: [{}]
});

const returnProbe = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Return Deterministic Probe',
    parameters: {
      mode: 'runOnceForAllItems',
      language: 'javaScript',
      jsCode: "return [{ json: { project: 'apic-portfolio', probe: 42 } }];"
    },
    position: [520, 300]
  },
  output: [{ project: 'apic-portfolio', probe: 42 }]
});

export default workflow('apic-portfolio-m0-runtime-probe', 'APIC | M0 | Runtime Probe')
  .add(startProbe)
  .to(returnProbe);
